import{_ as a,o as d,c as e,a2 as r}from"./chunks/framework.DzTVEUQW.js";const c=JSON.parse('{"title":"修炼体系","description":"","frontmatter":{},"headers":[],"relativePath":"system.md","filePath":"system.md","lastUpdated":null}'),h={name:"system.md"};function o(i,t,n,l,p,u){return d(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="修炼体系" tabindex="-1">修炼体系 <a class="header-anchor" href="#修炼体系" aria-label="Permalink to &quot;修炼体系&quot;">​</a></h1><blockquote><p>编程语言是功法，数据结构是法器，操作系统是天道规则，CPU架构是天地法则。程序员的成长就是修士的修炼。</p></blockquote><h2 id="六大境界" tabindex="-1">六大境界 <a class="header-anchor" href="#六大境界" aria-label="Permalink to &quot;六大境界&quot;">​</a></h2><h3 id="炼气期-—-刚会写代码" tabindex="-1">炼气期 — 刚会写代码 <a class="header-anchor" href="#炼气期-—-刚会写代码" aria-label="Permalink to &quot;炼气期 — 刚会写代码&quot;">​</a></h3><p>会变量、循环、函数，能写几百行的小程序。知道GitHub但不常用。</p><p>突破条件：能独立完成一个完整项目。从&quot;会写代码&quot;到&quot;能做东西&quot;。</p><p><a href="/lianqi/01-what-is-lianqi.html">看炼气期内容 →</a></p><hr><h3 id="筑基期-—-开始懂原理" tabindex="-1">筑基期 — 开始懂原理 <a class="header-anchor" href="#筑基期-—-开始懂原理" aria-label="Permalink to &quot;筑基期 — 开始懂原理&quot;">​</a></h3><p>懂数据结构与算法、操作系统、数据库、网络。不再只是&quot;能跑就行&quot;。</p><p>突破条件：能讲清楚&quot;一段代码从写完到运行，中间发生了什么&quot;。</p><p><a href="/zhuji/04-are-you-zhuji.html">看筑基期内容 →</a></p><hr><h3 id="金丹期-—-系统级理解" tabindex="-1">金丹期 — 系统级理解 <a class="header-anchor" href="#金丹期-—-系统级理解" aria-label="Permalink to &quot;金丹期 — 系统级理解&quot;">​</a></h3><p>懂编译原理、操作系统内核、计算机体系结构。能独立设计系统，有技术判断力。</p><p>突破条件：能从零解释一个技术方案的&quot;为什么&quot;，不只是&quot;怎么做&quot;。</p><p><a href="/jindan/09-compiler.html">看金丹期内容 →</a></p><hr><h3 id="元婴期-—-穿透到硬件" tabindex="-1">元婴期 — 穿透到硬件 <a class="header-anchor" href="#元婴期-—-穿透到硬件" aria-label="Permalink to &quot;元婴期 — 穿透到硬件&quot;">​</a></h3><p>懂指令集架构、CPU微架构、驱动开发。别人看到的是软件抽象，你看到的是电流在硅片上流动。</p><p>这是我自己的主场——嵌入式工程师天然在元婴期修炼。</p><p>突破条件：能在软件和硬件之间自由切换思维，从一行代码追到晶体管翻转。</p><p><a href="/yuanying/15-instruction-set.html">看元婴期内容 →</a></p><hr><h3 id="化神期-—-开始造技术" tabindex="-1">化神期 — 开始造技术 <a class="header-anchor" href="#化神期-—-开始造技术" aria-label="Permalink to &quot;化神期 — 开始造技术&quot;">​</a></h3><p>不只是用技术，而是创造技术。能设计编程语言、操作系统、框架。</p><p>Linus造了Linux和Git，Dennis Ritchie造了C语言和Unix。</p><p><a href="/huashen/21-create-language.html">看化神期内容 →</a></p><hr><h3 id="渡劫-大乘-—-改变行业" tabindex="-1">渡劫 / 大乘 — 改变行业 <a class="header-anchor" href="#渡劫-大乘-—-改变行业" aria-label="Permalink to &quot;渡劫 / 大乘 — 改变行业&quot;">​</a></h3><p>图灵定义了计算的本质，冯·诺依曼定义了计算机的架构。</p><p><a href="/dujie/26-von-neumann.html">看渡劫期内容 →</a></p><hr><h2 id="术语对照" tabindex="-1">术语对照 <a class="header-anchor" href="#术语对照" aria-label="Permalink to &quot;术语对照&quot;">​</a></h2><table tabindex="0"><thead><tr><th>修仙</th><th>技术</th><th>说明</th></tr></thead><tbody><tr><td>灵气</td><td>代码</td><td>程序员的根本能量</td></tr><tr><td>功法</td><td>编程语言</td><td>C/Python/Java，不同修炼路线</td></tr><tr><td>法器</td><td>数据结构</td><td>数组、链表、树、哈希</td></tr><tr><td>丹药</td><td>学习资源</td><td>经典教材和课程</td></tr><tr><td>天道规则</td><td>操作系统内核</td><td>进程调度、内存管理</td></tr><tr><td>天地法则</td><td>CPU指令集</td><td>x86/ARM/RISC-V</td></tr><tr><td>传送阵</td><td>网络</td><td>TCP/IP、HTTP</td></tr><tr><td>渡劫</td><td>认知跃迁</td><td>从会用到理解到创造</td></tr><tr><td>走火入魔</td><td>选型失误</td><td>架构设计错误</td></tr><tr><td>心魔</td><td>不懂原理滥用框架</td><td>表面能跑，底层不稳</td></tr><tr><td>宗门</td><td>开源社区</td><td>Linux社区、Apache</td></tr><tr><td>秘境</td><td>源码精读</td><td>内核源码、RFC</td></tr><tr><td>飞升</td><td>改变行业</td><td>图灵奖级别</td></tr></tbody></table>',35)])])}const q=a(h,[["render",o]]);export{c as __pageData,q as default};
